import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_src = r"""
#include <torch/extension.h>

torch::Tensor cute_depthwise_conv2d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

namespace cute_depthwise_detail {

constexpr int TILE_W = 128;
constexpr int TILE_H = 8;

__global__ void cute_depthwise_conv_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N,
    int C,
    int H,
    int W,
    int K,
    int OH,
    int OW,
    int stride,
    int padding,
    int dilation,
    bool has_bias)
{
    const int tx = threadIdx.x;
    const int n = blockIdx.z / C;
    const int c = blockIdx.z - n * C;

    const int ox0 = blockIdx.x * TILE_W;
    const int oy0 = blockIdx.y * TILE_H;

    const int input_tile_h = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
    extern __shared__ float smem[];

    auto sX = make_tensor(
        make_smem_ptr(smem),
        make_shape(input_tile_h, Int<TILE_W>{}),
        make_stride(Int<TILE_W>{}, Int<1>{}));

    auto gX = make_tensor(
        make_gmem_ptr(x),
        make_shape(N, C, H, W),
        make_stride(C * H * W, H * W, W, Int<1>{}));

    auto gO = make_tensor(
        make_gmem_ptr(out),
        make_shape(N, C, OH, OW),
        make_stride(C * OH * OW, OH * OW, OW, Int<1>{}));

    auto gW = make_tensor(
        make_gmem_ptr(weight),
        make_shape(C, K),
        make_stride(K, Int<1>{}));

    const int input_y0 = oy0 * stride - padding;

    for (int linear = tx;
         linear < input_tile_h * TILE_W;
         linear += blockDim.x) {
        const int iy = linear / TILE_W;
        const int ix = linear % TILE_W;
        const int gy = input_y0 + iy;
        const int output_x = ox0 + ix;
        const int gx = output_x * stride - padding;
        float v = 0.0f;
        if (n < N && c < C && gy >= 0 && gy < H && gx >= 0 && gx < W) {
            v = gX(n, c, gy, gx);
        }
        sX(iy, ix) = v;
    }

    __syncthreads();

    if (n >= N || c >= C) {
        return;
    }

    const int ox = ox0 + tx;
    if (ox >= OW) {
        return;
    }

    for (int oy_local = 0; oy_local < TILE_H; ++oy_local) {
        const int oy = oy0 + oy_local;
        if (oy >= OH) {
            continue;
        }

        float acc = has_bias ? bias[c] : 0.0f;

        const int shared_y0 = oy_local * stride;
        for (int ky = 0; ky < K; ++ky) {
            const int sy = shared_y0 + ky * dilation;
            acc += sX(sy, tx) * gW(c, ky);
        }

        gO(n, c, oy, ox) = acc;
    }
}

} // namespace cute_depthwise_detail


torch::Tensor cute_depthwise_conv2d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 4, "x must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
    TORCH_CHECK(
        weight.size(1) == 1 &&
        weight.size(2) >= 1 &&
        weight.size(3) == 1,
        "expected depthwise vertical convolution weights");

    const int N = static_cast<int>(x.size(0));
    const int C = static_cast<int>(x.size(1));
    const int H = static_cast<int>(x.size(2));
    const int W = static_cast<int>(x.size(3));
    const int K = static_cast<int>(weight.size(2));

    TORCH_CHECK(weight.size(0) == C, "weight channel mismatch");
    TORCH_CHECK(
        bias.numel() == 0 || bias.numel() == C,
        "bias must be empty or have one value per channel");

    const int OH =
        (H + 2 * static_cast<int>(padding) -
         static_cast<int>(dilation) * (K - 1) - 1) /
            static_cast<int>(stride) +
        1;

    const int OW =
        (W + 2 * static_cast<int>(padding) - 1) /
            static_cast<int>(stride) +
        1;

    TORCH_CHECK(OH >= 0 && OW >= 0, "invalid convolution output size");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();
    auto out = torch::empty({N, C, OH, OW}, x.options());

    const int input_tile_h =
        (cute_depthwise_detail::TILE_H - 1) * static_cast<int>(stride) +
        (K - 1) * static_cast<int>(dilation) + 1;
    const size_t shared_bytes =
        static_cast<size_t>(input_tile_h) *
        cute_depthwise_detail::TILE_W * sizeof(float);

    dim3 block(cute_depthwise_detail::TILE_W);
    dim3 grid(
        (OW + cute_depthwise_detail::TILE_W - 1) /
            cute_depthwise_detail::TILE_W,
        (OH + cute_depthwise_detail::TILE_H - 1) /
            cute_depthwise_detail::TILE_H,
        N * C);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_depthwise_detail::cute_depthwise_conv_kernel<<<
        grid, block, shared_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_c.numel() ? b_c.data_ptr<float>() : nullptr,
        out.data_ptr<float>(),
        N,
        C,
        H,
        W,
        K,
        OH,
        OW,
        static_cast<int>(stride),
        static_cast<int>(padding),
        static_cast<int>(dilation),
        b_c.numel() != 0);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE depthwise convolution launch failed");

    return out;
}
"""


cute_ext = load_inline(
    name="cute_depthwise_conv_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["cute_depthwise_conv2d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        bias: bool = False,
    ):
        super().__init__()
        self.conv2d = nn.Conv2d(
            in_channels,
            in_channels,
            kernel_size=(kernel_size, 1),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=in_channels,
            bias=bias,
        )
        self._stride = stride
        self._padding = padding
        self._dilation = dilation
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.conv2d.bias is None:
            bias = x.new_empty((0,))
        else:
            bias = self.conv2d.bias

        return self._ext.cute_depthwise_conv2d(
            x,
            self.conv2d.weight,
            bias,
            self._stride,
            self._padding,
            self._dilation,
        )

